import fs from 'node:fs';
import path from 'node:path';


const scssToTypeScript = (inputScssFile, outputTSFile, folder) => {
  const lines = fs.readFileSync(inputScssFile).toString().split('\n');
  let level = 0,
    ret = '// This file is automatically generated by the NodeJS script /assets/styles/scssToTypeScript.js. If\n'
      + '// you want to change, add or delete some values, do this in the corresponding SCSS file\n'
      + `// ./_index.scss and run the above script with argument "${folder}" again.\n`;

  for (let line of lines) {
    // remove inline comments and whitespaces from the beginning and end of the line
    const posComment = line.indexOf('//');
    if (posComment >= 0) {
      line = line.substring(0, posComment);
    }
    line = line.trim();

    if (level === 0) {
      // -------------------------------------------------------------------------------------------
      // Search for the beginning of a main map to export.
      // -------------------------------------------------------------------------------------------

      const { startMap } = line.match(/^\/\*\s*export\s*\*\/\s*\$(?<startMap>[a-z]\w*)\s*:\s*\($/i)?.groups ?? {};

      if (startMap) {
        ret += '\n';
        ret += `export const ${startMap} = Object.freeze({\n`;
        level++;
      }
    } else if (/^\);$/.test(line)) {
      // -------------------------------------------------------------------------------------------
      // Detect the end of the main map.
      // -------------------------------------------------------------------------------------------

      while (level-- > 1) {
        ret += `${'  '.repeat(level)}}),\n`;
      }

      ret += '});\n';
      level = 0;
    } else {
      const { startNestedMap } = line.match(/^(?<startNestedMap>[a-z]\w*)\s*:\s*\($/i)?.groups ?? {};

      if (startNestedMap) {
        // -----------------------------------------------------------------------------------------
        // Detect the beginning of a nested map inside the current map.
        // -----------------------------------------------------------------------------------------

        ret += `${'  '.repeat(level)}${startNestedMap}: Object.freeze({\n`;
        level++;
      } else if (/^\),$/.test(line)) {
        // -----------------------------------------------------------------------------------------
        // Detect the end of the nested map.
        // -----------------------------------------------------------------------------------------

        level--;
        ret += `${'  '.repeat(level)}}),\n`;
      } else {
        // -----------------------------------------------------------------------------------------
        // Add a valid map entry (key value pair).
        // -----------------------------------------------------------------------------------------

        const { key, value } = line.match(/^"?(?<key>\w+)"?\s*:\s*(?<value>.+)$/i)?.groups ?? {};

        if (key) {
          let parsedValue = value;

          if (parsedValue.slice(-1) === ',') {
            parsedValue = parsedValue.slice(0, -1).trim();
          }

          // A single name in quotes - a key of the palette, quoted in SCSS because some keys are CSS
          // colour names as well - is the name itself in TypeScript. Any other quoted value keeps
          // its quotes, as a shadow list does.
          parsedValue = parsedValue.replace(/^"(?<name>[a-z]\w*)"$/i, '$<name>');

          if (String(Number(parsedValue)) !== parsedValue) {
            parsedValue = `'${parsedValue}'`;
          }

          ret += `${'  '.repeat(level)}${key}: ${parsedValue},\n`;
        }
      }
    }
  }

  fs.writeFileSync(outputTSFile, ret);
};


if (process.argv.length <= 2) {
  console.log('\x1b[31mERROR: You have to enter a style folder "color", "layout", "space" or "typo" as argument.\x1b[0m'); // eslint-disable-line no-console
  process.exit(1);
}

if (
  !process.argv.includes('color', 2)
  && !process.argv.includes('layout', 2)
  && !process.argv.includes('space', 2)
  && !process.argv.includes('typo', 2)
) {
  console.log(`\x1b[31mERROR: The given style folder "${process.argv[2]}" is invalid, only "color", "layout", "space" or "typo" are allowed.\x1b[0m`); // eslint-disable-line no-console
  process.exit(1);
}

const [,, folder] = process.argv;
const inputScssFile = path.join(import.meta.dirname, `${folder}/_index.scss`);
const outputTSFile = path.join(import.meta.dirname, `${folder}/_index.ts`);

if (!fs.existsSync(inputScssFile)) {
  console.log(`\x1b[31mERROR: The input SCSS file "${inputScssFile}" seems not to exist.\x1b[0m`); // eslint-disable-line no-console
  process.exit(1);
}

scssToTypeScript(inputScssFile, outputTSFile, folder);
